package auth

import (
	"context"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"github.com/superplanehq/superplane/pkg/authorization"
	"github.com/superplanehq/superplane/pkg/models"
	pbAuth "github.com/superplanehq/superplane/pkg/protos/authorization"
	pb "github.com/superplanehq/superplane/pkg/protos/roles"
	"github.com/superplanehq/superplane/test/support"
)

func Test_UpdateRole(t *testing.T) {
	r := support.Setup(t)
	ctx := context.Background()
	orgID := r.Organization.ID.String()
	canvasPath := "canvases"
	secretPath := "secrets"

	// Create a custom role first
	customRoleDef := &authorization.RoleDefinition{
		Name:       "test-custom-role",
		DomainType: models.DomainTypeOrganization,
		Permissions: []*authorization.Permission{
			{
				Resource:   canvasPath,
				Action:     "read",
				DomainType: models.DomainTypeOrganization,
			},
		},
	}
	err := r.AuthService.CreateCustomRole(orgID, customRoleDef)
	require.NoError(t, err)

	t.Run("successful custom role update", func(t *testing.T) {
		req := &pb.Role_Spec{
			Permissions: []*pbAuth.Permission{
				{
					Resource:   canvasPath,
					Action:     "read",
					DomainType: pbAuth.DomainType_DOMAIN_TYPE_ORGANIZATION,
				},
				{
					Resource:   canvasPath,
					Action:     "update",
					DomainType: pbAuth.DomainType_DOMAIN_TYPE_ORGANIZATION,
				},
				{
					Resource:   secretPath,
					Action:     "read",
					DomainType: pbAuth.DomainType_DOMAIN_TYPE_ORGANIZATION,
				},
			},
		}

		resp, err := UpdateRole(ctx, models.DomainTypeOrganization, orgID, "test-custom-role", req, r.AuthService)
		require.NoError(t, err)
		assert.NotNil(t, resp)

		roleDef, err := r.AuthService.GetRoleDefinition("test-custom-role", models.DomainTypeOrganization, orgID)
		require.NoError(t, err)
		assert.Equal(t, "test-custom-role", roleDef.Name)
		assert.Len(t, roleDef.Permissions, 3)
	})

	t.Run("successful custom role update with inheritance", func(t *testing.T) {
		req := &pb.Role_Spec{
			InheritedRole: &pb.Role{
				Metadata: &pb.Role_Metadata{
					Name: models.RoleOrgViewer,
				},
			},
			Permissions: []*pbAuth.Permission{
				{
					Resource:   canvasPath,
					Action:     "create",
					DomainType: pbAuth.DomainType_DOMAIN_TYPE_ORGANIZATION,
				},
			},
		}

		resp, err := UpdateRole(ctx, models.DomainTypeOrganization, orgID, "test-custom-role", req, r.AuthService)
		require.NoError(t, err)
		assert.NotNil(t, resp)

		roleDef, err := r.AuthService.GetRoleDefinition("test-custom-role", models.DomainTypeOrganization, orgID)
		require.NoError(t, err)
		assert.Equal(t, "test-custom-role", roleDef.Name)
		assert.NotNil(t, roleDef.InheritsFrom)
		assert.Equal(t, models.RoleOrgViewer, roleDef.InheritsFrom.Name)
		assert.Len(t, roleDef.Permissions, 1)
	})

	t.Run("invalid request - missing role name", func(t *testing.T) {
		req := &pb.Role_Spec{
			Permissions: []*pbAuth.Permission{
				{
					Resource:   canvasPath,
					Action:     "read",
					DomainType: pbAuth.DomainType_DOMAIN_TYPE_ORGANIZATION,
				},
			},
		}

		_, err := UpdateRole(ctx, models.DomainTypeOrganization, orgID, "", req, r.AuthService)
		assert.Error(t, err)
		assert.Contains(t, err.Error(), "role name must be specified")
	})

	t.Run("invalid request - default role name", func(t *testing.T) {
		req := &pb.Role_Spec{
			Permissions: []*pbAuth.Permission{
				{
					Resource:   canvasPath,
					Action:     "read",
					DomainType: pbAuth.DomainType_DOMAIN_TYPE_ORGANIZATION,
				},
			},
		}

		_, err := UpdateRole(ctx, models.DomainTypeOrganization, orgID, models.RoleOrgAdmin, req, r.AuthService)
		assert.Error(t, err)
		assert.Contains(t, err.Error(), "cannot update default role")
	})

	t.Run("invalid request - nonexistent role", func(t *testing.T) {
		req := &pb.Role_Spec{
			Permissions: []*pbAuth.Permission{
				{
					Resource:   canvasPath,
					Action:     "read",
					DomainType: pbAuth.DomainType_DOMAIN_TYPE_ORGANIZATION,
				},
			},
		}

		_, err := UpdateRole(ctx, models.DomainTypeOrganization, orgID, "nonexistent-role", req, r.AuthService)
		assert.Error(t, err)
		assert.Contains(t, err.Error(), "role not found")
	})

	t.Run("invalid request - nonexistent inherited role", func(t *testing.T) {
		req := &pb.Role_Spec{
			InheritedRole: &pb.Role{
				Metadata: &pb.Role_Metadata{
					Name: "nonexistent-role",
				},
			},
			Permissions: []*pbAuth.Permission{
				{
					Resource:   canvasPath,
					Action:     "read",
					DomainType: pbAuth.DomainType_DOMAIN_TYPE_ORGANIZATION,
				},
			},
		}

		_, err := UpdateRole(ctx, models.DomainTypeOrganization, orgID, "test-custom-role", req, r.AuthService)
		assert.Error(t, err)
		assert.Contains(t, err.Error(), "inherited role not found")
	})
}

package auth

import (
	"context"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"github.com/superplanehq/superplane/pkg/models"
	pbAuth "github.com/superplanehq/superplane/pkg/protos/authorization"
	"github.com/superplanehq/superplane/test/support"
)

func Test__ListUsers(t *testing.T) {
	r := support.Setup(t)

	t.Run("returns role assignments", func(t *testing.T) {
		resp, err := ListUsers(context.Background(), models.DomainTypeOrganization, r.Organization.ID.String(), true, r.AuthService)
		require.NoError(t, err)
		require.NotNil(t, resp)
		assert.Len(t, resp.Users, 1)

		for _, user := range resp.Users {
			assert.NotEmpty(t, user.Metadata.Id)
			assert.NotEmpty(t, user.Status.Roles)
			assert.NotEmpty(t, user.Status.AccountProviders)
			for _, role := range user.Status.Roles {
				assert.NotEmpty(t, role)
				assert.Equal(t, pbAuth.DomainType_DOMAIN_TYPE_ORGANIZATION, role.DomainType)
				assert.Equal(t, r.Organization.ID.String(), role.DomainId)
			}
		}
	})

	t.Run("returns no role assignments", func(t *testing.T) {
		resp, err := ListUsers(context.Background(), models.DomainTypeOrganization, r.Organization.ID.String(), false, r.AuthService)
		require.NoError(t, err)
		require.NotNil(t, resp)
		assert.Len(t, resp.Users, 1)
		assert.Empty(t, resp.Users[0].Status.Roles)
	})
}

package auth

import (
	"context"
	"testing"

	"github.com/google/uuid"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"github.com/superplanehq/superplane/pkg/authorization"
	"github.com/superplanehq/superplane/pkg/models"
	"github.com/superplanehq/superplane/test/support"
)

func Test_DeleteRole(t *testing.T) {
	r := support.Setup(t)
	ctx := context.Background()
	orgID := r.Organization.ID.String()
	canvasPath := "canvases"

	customRoleDef := &authorization.RoleDefinition{
		Name:       "test-custom-role-to-delete",
		DomainType: models.DomainTypeOrganization,
		Permissions: []*authorization.Permission{
			{
				Resource:   canvasPath,
				Action:     "read",
				DomainType: models.DomainTypeOrganization,
			},
			{
				Resource:   canvasPath,
				Action:     "update",
				DomainType: models.DomainTypeOrganization,
			},
		},
	}

	err := r.AuthService.CreateCustomRole(orgID, customRoleDef)
	require.NoError(t, err)

	t.Run("successful custom role deletion", func(t *testing.T) {
		roleDef, err := r.AuthService.GetRoleDefinition("test-custom-role-to-delete", models.DomainTypeOrganization, orgID)
		require.NoError(t, err)
		assert.Equal(t, "test-custom-role-to-delete", roleDef.Name)

		resp, err := DeleteRole(ctx, models.DomainTypeOrganization, orgID, "test-custom-role-to-delete", r.AuthService)
		require.NoError(t, err)
		assert.NotNil(t, resp)

		_, err = r.AuthService.GetRoleDefinition("test-custom-role-to-delete", models.DomainTypeOrganization, orgID)
		assert.Error(t, err)
	})

	t.Run("invalid request - missing role name", func(t *testing.T) {
		_, err := DeleteRole(ctx, models.DomainTypeOrganization, orgID, "", r.AuthService)
		assert.Error(t, err)
		assert.Contains(t, err.Error(), "role name must be specified")
	})

	t.Run("invalid request - invalid domain type", func(t *testing.T) {
		_, err := DeleteRole(ctx, "invalid-domain-type", orgID, "test-role", r.AuthService)
		assert.Error(t, err)
		assert.Contains(t, err.Error(), "role not found")
	})

	t.Run("invalid request - default role name", func(t *testing.T) {
		_, err := DeleteRole(ctx, models.DomainTypeOrganization, orgID, models.RoleOrgAdmin, r.AuthService)
		assert.Error(t, err)
		assert.Contains(t, err.Error(), "cannot delete default role")
	})

	t.Run("invalid request - nonexistent role", func(t *testing.T) {
		_, err := DeleteRole(ctx, models.DomainTypeOrganization, orgID, "nonexistent-role", r.AuthService)
		assert.Error(t, err)
		assert.Contains(t, err.Error(), "role not found")
	})

	t.Run("invalid request - invalid UUID", func(t *testing.T) {
		_, err := DeleteRole(ctx, models.DomainTypeOrganization, "invalid-uuid", "test-role", r.AuthService)
		assert.Error(t, err)
		assert.Contains(t, err.Error(), "role not found")
	})

	t.Run("delete role that users are assigned to", func(t *testing.T) {
		customRoleWithUsers := &authorization.RoleDefinition{
			Name:       "test-role-with-users",
			DomainType: models.DomainTypeOrganization,
			Permissions: []*authorization.Permission{
				{
					Resource:   canvasPath,
					Action:     "read",
					DomainType: models.DomainTypeOrganization,
				},
			},
		}
		err = r.AuthService.CreateCustomRole(orgID, customRoleWithUsers)
		require.NoError(t, err)

		userID := uuid.New().String()
		err = r.AuthService.AssignRole(userID, "test-role-with-users", orgID, models.DomainTypeOrganization)
		require.NoError(t, err)

		resp, err := DeleteRole(ctx, models.DomainTypeOrganization, orgID, "test-role-with-users", r.AuthService)
		require.NoError(t, err)
		assert.NotNil(t, resp)

		_, err = r.AuthService.GetRoleDefinition("test-role-with-users", models.DomainTypeOrganization, orgID)
		assert.Error(t, err)

		userRoles, err := r.AuthService.GetUserRolesForOrg(userID, orgID)
		require.NoError(t, err)
		for _, role := range userRoles {
			assert.NotEqual(t, "test-role-with-users", role.Name)
		}
	})

	t.Run("delete role removes users with only that role from org", func(t *testing.T) {
		customRoleOnly := &authorization.RoleDefinition{
			Name:       "test-role-only-users",
			DomainType: models.DomainTypeOrganization,
			Permissions: []*authorization.Permission{
				{
					Resource:   canvasPath,
					Action:     "read",
					DomainType: models.DomainTypeOrganization,
				},
			},
		}
		err = r.AuthService.CreateCustomRole(orgID, customRoleOnly)
		require.NoError(t, err)

		account, err := models.CreateAccount("only-role-user", "only-role-user@test.com")
		require.NoError(t, err)
		user, err := models.CreateUser(r.Organization.ID, account.ID, account.Email, account.Name)
		require.NoError(t, err)

		err = r.AuthService.AssignRole(user.ID.String(), "test-role-only-users", orgID, models.DomainTypeOrganization)
		require.NoError(t, err)

		resp, err := DeleteRole(ctx, models.DomainTypeOrganization, orgID, "test-role-only-users", r.AuthService)
		require.NoError(t, err)
		assert.NotNil(t, resp)

		_, err = models.FindActiveUserByID(orgID, user.ID.String())
		assert.Error(t, err)
	})

	t.Run("delete role reassigns groups to viewer role", func(t *testing.T) {
		customRoleForGroup := &authorization.RoleDefinition{
			Name:       "test-role-for-group",
			DomainType: models.DomainTypeOrganization,
			Permissions: []*authorization.Permission{
				{
					Resource:   canvasPath,
					Action:     "read",
					DomainType: models.DomainTypeOrganization,
				},
			},
		}
		err = r.AuthService.CreateCustomRole(orgID, customRoleForGroup)
		require.NoError(t, err)

		groupName := "test-group-role-reassign"
		err = r.AuthService.CreateGroup(orgID, models.DomainTypeOrganization, groupName, "test-role-for-group", "Test Group", "Test Group")
		require.NoError(t, err)

		resp, err := DeleteRole(ctx, models.DomainTypeOrganization, orgID, "test-role-for-group", r.AuthService)
		require.NoError(t, err)
		assert.NotNil(t, resp)

		groupRole, err := r.AuthService.GetGroupRole(orgID, models.DomainTypeOrganization, groupName)
		require.NoError(t, err)
		assert.Equal(t, models.RoleOrgViewer, groupRole)
	})
}

package auth

import (
	"context"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"github.com/superplanehq/superplane/pkg/models"
	"github.com/superplanehq/superplane/test/support"
)

func Test_ListRoles(t *testing.T) {
	r := support.Setup(t)
	ctx := context.Background()
	orgID := r.Organization.ID.String()

	t.Run("successful list roles", func(t *testing.T) {
		resp, err := ListRoles(ctx, models.DomainTypeOrganization, orgID, r.AuthService)
		require.NoError(t, err)
		assert.Equal(t, len(resp.Roles), 3)

		roleNames := make([]string, len(resp.Roles))
		for i, role := range resp.Roles {
			roleNames[i] = role.Metadata.Name
		}
		assert.Contains(t, roleNames, models.RoleOrgViewer)
		assert.Contains(t, roleNames, models.RoleOrgAdmin)
		assert.Contains(t, roleNames, models.RoleOrgOwner)
		assert.Len(t, resp.Roles, 3)

		// Test beautiful display names and descriptions for each role
		for _, role := range resp.Roles {
			assert.NotEmpty(t, role.Spec.DisplayName, "DisplayName should not be empty for role %s", role.Metadata.Name)
			assert.NotEmpty(t, role.Spec.Description, "Description should not be empty for role %s", role.Metadata.Name)

			switch role.Metadata.Name {
			case models.RoleOrgOwner:
				assert.Equal(t, "Owner", role.Spec.DisplayName)
				assert.Contains(t, role.Spec.Description, "Full control over organization settings")
			case models.RoleOrgAdmin:
				assert.Equal(t, "Admin", role.Spec.DisplayName)
				assert.Contains(t, role.Spec.Description, "Can manage canvases, users, groups, and roles")
			case models.RoleOrgViewer:
				assert.Equal(t, "Viewer", role.Spec.DisplayName)
				assert.Contains(t, role.Spec.Description, "Read-only access to organization resources")
			}
		}
	})

}

package auth

import (
	"context"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"github.com/superplanehq/superplane/pkg/models"
	pbAuth "github.com/superplanehq/superplane/pkg/protos/authorization"
	pb "github.com/superplanehq/superplane/pkg/protos/groups"
	"github.com/superplanehq/superplane/test/support"
)

func Test_ListGroups(t *testing.T) {
	r := support.Setup(t)
	ctx := context.Background()
	orgID := r.Organization.ID.String()

	require.NoError(t, r.AuthService.CreateGroup(orgID, models.DomainTypeOrganization, "test-group-1", models.RoleOrgAdmin, "Test Group 1", "A test group"))
	require.NoError(t, r.AuthService.CreateGroup(orgID, models.DomainTypeOrganization, "test-group-2", models.RoleOrgViewer, "Test Group 2", "Another test group"))

	t.Run("successful list groups", func(t *testing.T) {
		resp, err := ListGroups(ctx, models.DomainTypeOrganization, orgID, r.AuthService)
		require.NoError(t, err)
		assert.NotNil(t, resp)
		assert.Len(t, resp.Groups, 2)

		// Check that groups have the correct structure
		for _, group := range resp.Groups {
			assert.NotEmpty(t, group.Metadata.Name)
			assert.Equal(t, pbAuth.DomainType_DOMAIN_TYPE_ORGANIZATION, group.Metadata.DomainType)
			assert.Equal(t, orgID, group.Metadata.DomainId)
			assert.Contains(t, []string{"org_admin", "org_viewer"}, group.Spec.Role)
			assert.GreaterOrEqual(t, group.Status.MembersCount, int32(0))
			assert.NotEmpty(t, group.Metadata.CreatedAt)
			assert.NotEmpty(t, group.Metadata.UpdatedAt)
		}

		// Check specific group names
		groupNames := make([]string, len(resp.Groups))
		for i, group := range resp.Groups {
			groupNames[i] = group.Metadata.Name
		}
		assert.Contains(t, groupNames, "test-group-1")
		assert.Contains(t, groupNames, "test-group-2")
	})

	t.Run("groups with metadata have timestamps", func(t *testing.T) {
		require.NoError(t, r.AuthService.AddUserToGroup(orgID, "org", "test-user-1", "test-group-1"))

		resp, err := ListGroups(ctx, models.DomainTypeOrganization, orgID, r.AuthService)
		require.NoError(t, err)

		var groupWithMetadata *pb.Group
		for _, group := range resp.Groups {
			if group.Metadata.Name == "test-group-1" {
				groupWithMetadata = group
				break
			}
		}

		require.NotNil(t, groupWithMetadata)
		assert.NotEmpty(t, groupWithMetadata.Metadata.CreatedAt)
		assert.NotEmpty(t, groupWithMetadata.Metadata.UpdatedAt)
		assert.Equal(t, int32(1), groupWithMetadata.Status.MembersCount)
		assert.Equal(t, "Test Group 1", groupWithMetadata.Spec.DisplayName)
		assert.Equal(t, "A test group", groupWithMetadata.Spec.Description)
	})
}

